    "1215347a-8e75-42f3-a249-701609194a20": {
      "id": "1215347a-8e75-42f3-a249-701609194a20",
      "message": {
        "id": "1215347a-8e75-42f3-a249-701609194a20",
        "author": {
          "role": "user",
