def main_chain(obj):
    mapping=obj["mapping"]
    nid=obj["current_node"]
    chain=[]
    seen=set()
    while nid and nid not in seen:
        seen.add(nid)
        node=mapping.get(nid)
        if not node: break
        chain.append(node)
        nid=node.get("parent")
    chain.reverse()
    return chain

def msg_text(node):
    m=node.get("message")
    if not m: return None,None
    role=(m.get("author") or {}).get("role")
    c=m.get("content") or {}
    typ=c.get("content_type")
    if typ=="text":
        parts=c.get("parts") or []
        text="\n".join(str(x) for x in parts if isinstance(x,(str,int,float)))
    elif typ in ("code","thoughts","reasoning_recap","multimodal_text"):
        if typ=="code":
            text=c.get("text") or ""
        elif typ=="reasoning_recap":
            text=c.get("content") or ""
        elif typ=="thoughts":
            text="\n".join((x.get("summary","")+" "+x.get("content","")) for x in c.get("thoughts",[]) if isinstance(x,dict))
        else:
            parts=c.get("parts") or []
            text="\n".join(str(x) for x in parts if isinstance(x,str))
    else:
        text=""
    return role,text

